 "reason": {
  "es": "衆議院《しゅうぎいん》の委員長《いいんちょう》の説明《せつめい》では、この条約《じょうやく》は、相手《あいて》の国《くに》で刑《けい》（罪《つみ》に対《たい》するばつ）を受《う》けている自分《じぶん》の国《くに》の人《ひと》を、自分《じぶん》の国《くに》に送《おく》るための条件《じょうけん》や手続《てつづ》きを決《き》めるものです。",
  "hs": "衆議院の外務委員長の報告では、この条約は、相手の国で刑に服している自分の国の受刑者《じゅけいしゃ》を本国に移送《いそう》する（送る）ための条件や手続きを定めるものだと説明された。",
  "std": "衆議院外務委員長の報告によると、条約は、相手国で刑に服している自国民の受刑者を本国に移送するための条件、手続等を定めるものとされている。",
  "univ": "衆議院外務委員長の報告では、本条約は、相手国で刑に服している自国民受刑者を本国に移送するための条件、手続等について定めるものとされている。"
 },
 "who": {
  "es": "日本《にほん》とベトナムの国《くに》と、相手《あいて》の国《くに》で刑《けい》を言《い》いわたされた人《ひと》に関係《かんけい》します。送《おく》られるのは、判決《はんけつ》が決《き》まっていて、本人《ほんにん》が送《おく》られることに賛成《さんせい》しているなどの条件《じょうけん》にあう人《ひと》です。",
  "hs": "日本とベトナムの両国と、相手の国で刑を言いわたされた人。移送《いそう》されるのは、判決が確定《かくてい》し、本人が移送に同意しているなどの条件を満たす人。",
  "std": "日本とベトナムの両国（移送国・受入国）と、相手国で刑を言い渡された者。移送されるのは、判決が確定し、本人が移送に同意しているなどの条件を満たす者。",
  "univ": "日本国及びベトナム社会主義共和国の両締約国（移送国及び受入国）並びに刑を言い渡された者。移送の対象は、判決が確定していること、刑を言い渡された者が移送に同意していること、双罰性を構成すること等の条件が満たされている者に限られる。"
 },
 "committee": {
  "es": "衆議院《しゅうぎいん》では、5月《がつ》19日《にち》に、この条約《じょうやく》など5件《けん》を外務委員会《がいむいいんかい》が任《まか》されました。20日《はつか》に茂木《もてぎ》外務大臣《がいむだいじん》が説明《せつめい》し、22日《にち》に質問《しつもん》をしました。5件《けん》とも全員《ぜんいん》の賛成《さんせい》で、認《みと》めるべきだと決《き》めました。参議院《さんぎいん》では、外交防衛委員会《がいこうぼうえいいいんかい》が、この条約《じょうやく》など3件《けん》をまとめて調《しら》べました。質問《しつもん》では、両方《りょうほう》の国《くに》で罪《つみ》になる行《おこな》いにかぎるという考《かんが》え方《かた》（双方可罰性《そうほうかばつせい》）のあつかいや、日本《にほん》にいる外国人《がいこくじん》の受刑者《じゅけいしゃ》（刑務所《けいむしょ》に入《はい》っている人《ひと》）の今《いま》のようす、これまでに受刑者《じゅけいしゃ》を送《おく》った数《かず》などが取《と》り上《あ》げられました。決《き》めた結果《けっか》、3件《けん》とも全員《ぜんいん》の賛成《さんせい》で、認《みと》めるべきだとなりました。",
  "hs": "衆議院では、5月19日にこの条約など5件が外務委員会に付託《ふたく》された（任された）。20日に茂木《もてぎ》外務大臣が提案の理由を説明し、22日に質疑をした。順に採決し、5件はいずれも全会一致で承認すべきだと決めた。参議院では、外交防衛委員会がこの条約など3件をまとめて審議《しんぎ》した。質疑では、受刑者移送条約での双方可罰性《そうほうかばつせい》（両方の国で罪になる行為にかぎること）の原則のあつかい、外国人受刑者の現状とこれまでの受刑者移送の実績などが取り上げられた。採決の結果、3件はいずれも全会一致で承認すべきだと決めた。",
  "std": "衆議院では、5月19日に外務委員会に付託され、20日に茂木外務大臣が提案理由を説明し、22日に質疑を行った。順次採決し、5件はいずれも全会一致で承認すべきものと議決した。参議院の外交防衛委員会では、3件を一括して審査し、受刑者移送条約における双方可罰性の原則の扱い、外国人受刑者の現状とこれまでの受刑者移送の実績などについて質疑が行われた。採決の結果、3件はいずれも全会一致で承認すべきものと決定した。",
  "univ": "衆議院では、本件を含む5件が去る5月19日外務委員会に付託され、翌20日茂木外務大臣から提案理由の説明を聴取し、22日に質疑を行い、順次採決を行った結果、5件はいずれも全会一致をもって承認すべきものと議決した。参議院では、外交防衛委員会において本件を含む3件を一括して議題とし、受刑者移送条約における双方可罰性の原則の扱い、外国人受刑者の現状とこれまでの受刑者移送の実績等について質疑が行われた。順次採決の結果、3件はいずれも全会一致をもって承認すべきものと決定した。"
 },
